WITH filtered_shipments AS (SELECT *, CONCAT_WS(',', carrier, status) AS carrier_status_key FROM shipments WHERE order_id IN (8, 19) AND cost BETWEEN 45 AND 92), status_summary AS (SELECT status, ROUND((100 * SUM(CASE WHEN status = 'IN_TRANSIT' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_in_transit, COUNT(cost) AS cost_count FROM filtered_shipments GROUP BY status) SELECT * FROM status_summary ORDER BY status LIMIT 5;
